import Database from "better-sqlite3";
import { randomBytes, createHash } from "crypto";

const dbPath = "/home/user/qwik-app/db.sqlite";

// Open the database
export const db = new Database(dbPath);

// Enable WAL mode for better concurrency and to prevent database locking issues
db.pragma("journal_mode = WAL");

// Initialize the table if it does not exist
db.exec(`
  CREATE TABLE IF NOT EXISTS api_keys (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    key_prefix TEXT NOT NULL,
    hashed_key TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('active', 'revoked')),
    created_at TEXT NOT NULL
  )
`);

export interface ApiKeyRow {
  id: number;
  name: string;
  key_prefix: string;
  hashed_key: string;
  status: "active" | "revoked";
  created_at: string;
}

export function generateApiKey(): { key: string; prefix: string; hashedKey: string } {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  let randomStr = "";
  const bytes = randomBytes(32);
  for (let i = 0; i < 32; i++) {
    randomStr += chars[bytes[i] % chars.length];
  }

  const key = `qk_${randomStr}`;
  const prefix = key.slice(0, 7); // First 7 characters: e.g. 'qk_abcd'

  const hashedKey = hashKey(key);

  return { key, prefix, hashedKey };
}

export function hashKey(key: string): string {
  return createHash("sha256").update(key).digest("hex");
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { db, generateApiKey } from "../../../../../lib/db";

export const onPost: RequestHandler = async (event) => {
  try {
    const body = (await event.parseBody()) as { name?: string } | null;
    const name = body?.name;

    if (!name || typeof name !== "string" || name.trim() === "") {
      event.json(400, { error: "Name is required and must be a non-empty string" });
      return;
    }

    const { key, prefix, hashedKey } = generateApiKey();
    const createdAt = new Date().toISOString();

    const stmt = db.prepare(`
      INSERT INTO api_keys (name, key_prefix, hashed_key, status, created_at)
      VALUES (?, ?, ?, ?, ?)
    `);
    const result = stmt.run(name.trim(), prefix, hashedKey, "active", createdAt);
    const id = Number(result.lastInsertRowid);

    event.json(201, {
      id,
      name: name.trim(),
      prefix,
      key,
      status: "active",
      created_at: createdAt,
    });
  } catch (error: any) {
    event.json(500, { error: error?.message || "Internal Server Error" });
  }
};

export const onGet: RequestHandler = async (event) => {
  try {
    const stmt = db.prepare(`
      SELECT id, name, key_prefix AS prefix, status, created_at
      FROM api_keys
      ORDER BY id DESC
    `);
    const keys = stmt.all();
    event.json(200, keys);
  } catch (error: any) {
    event.json(500, { error: error?.message || "Internal Server Error" });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { db } from "../../../../../../lib/db";

export const onPost: RequestHandler = async (event) => {
  try {
    const idStr = event.params.id;
    const id = parseInt(idStr, 10);

    if (isNaN(id)) {
      event.json(400, { error: "Invalid key ID" });
      return;
    }

    // Check if the key exists
    const checkStmt = db.prepare("SELECT id FROM api_keys WHERE id = ?");
    const keyExists = checkStmt.get(id);

    if (!keyExists) {
      event.json(404, { error: "Key not found" });
      return;
    }

    // Update the status to 'revoked'
